values
  ('6a022a9c-b8d7-42e1-9657-537b97077495', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Spectroscopy II', 'This module establishes spectroscopy ii as the course''s first working framework. It supplies the language and representations needed before the path advances to aromaticity.', 0),
  ('d89da874-447f-4b98-acd7-e1612cb03a1a', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '6a022a9c-b8d7-42e1-9657-537b97077495', 'subtopic'::public.curated_course_node_type, '13C NMR', '13C NMR identifies a specific object, distinction, or relationship within spectroscopy ii. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before coupling detail because that next topic assumes this starting point.', 0),
  ('a842da8c-42f6-4e4e-aef3-940e4cb334f6', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '6a022a9c-b8d7-42e1-9657-537b97077495', 'subtopic'::public.curated_course_node_type, 'Coupling detail', 'Coupling detail identifies a specific object, distinction, or relationship within spectroscopy ii. Learners need to recognize and use it before combining this module''s ideas in later work. After 13c nmr, coupling detail supplies what is needed to address combined ir/nmr/ms structure problems.', 1),
  ('4e3bd3ae-9120-45a0-909d-7aaf8e53e482', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '6a022a9c-b8d7-42e1-9657-537b97077495', 'subtopic'::public.curated_course_node_type, 'Combined IR/NMR/MS structure problems', 'Combined IR/NMR/MS structure problems identifies a specific object, distinction, or relationship within spectroscopy ii. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, combined ir/nmr/ms structure problems carries the completed idea into aromaticity.', 2),
  ('1125919f-0157-4cfe-be22-2f6d18d6064b', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Aromaticity', 'This module builds directly on spectroscopy ii and develops aromaticity. It belongs here because its methods and distinctions are prerequisites for electrophilic aromatic substitution.', 1),
  ('624a32e3-fef9-4b4b-a96e-5a877bc9975f', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '1125919f-0157-4cfe-be22-2f6d18d6064b', 'subtopic'::public.curated_course_node_type, 'Hückel rule', 'Hückel rule identifies a specific object, distinction, or relationship within aromaticity. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before resonance energy because that next topic assumes this starting point.', 0),
  ('2b4cd762-bfa7-4f60-ac40-b0afb72aeb1d', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '1125919f-0157-4cfe-be22-2f6d18d6064b', 'subtopic'::public.curated_course_node_type, 'Resonance energy', 'Resonance energy is a governing quantity in aromaticity, linking local calculations to system-level behavior and offering a consistency check. After hückel rule, resonance energy supplies what is needed to address antiaromatic/nonaromatic systems.', 1),
  ('81e68790-a958-4b4b-b804-4fdc79c804bf', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '1125919f-0157-4cfe-be22-2f6d18d6064b', 'subtopic'::public.curated_course_node_type, 'Antiaromatic/nonaromatic systems', 'Antiaromatic/nonaromatic systems gives aromaticity a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, antiaromatic/nonaromatic systems carries the completed idea into electrophilic aromatic substitution.', 2),
  ('cb68a3ff-e9c2-47db-81a8-0c5f335fa781', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Electrophilic aromatic substitution', 'This module builds directly on aromaticity and develops electrophilic aromatic substitution. It belongs here because its methods and distinctions are prerequisites for nucleophilic aromatic substitution and benzylic chemistry.', 2),
  ('7ea0cdf3-8bfa-482c-b63a-3c0eb11ed37e', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'cb68a3ff-e9c2-47db-81a8-0c5f335fa781', 'subtopic'::public.curated_course_node_type, 'Mechanisms', 'Mechanisms supplies the causal sequence within electrophilic aromatic substitution, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before directing effects because that next topic assumes this starting point.', 0),
  ('7a3c874c-2e05-4e1c-a4e5-329c469d02d7', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'cb68a3ff-e9c2-47db-81a8-0c5f335fa781', 'subtopic'::public.curated_course_node_type, 'Directing effects', 'Directing effects identifies a specific object, distinction, or relationship within electrophilic aromatic substitution. Learners need to recognize and use it before combining this module''s ideas in later work. After mechanisms, directing effects supplies what is needed to address synthesis planning.', 1),
  ('e989a2f1-f8e9-4beb-8e79-6af41f4105f0', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'cb68a3ff-e9c2-47db-81a8-0c5f335fa781', 'subtopic'::public.curated_course_node_type, 'Synthesis planning', 'Synthesis planning turns the theory of electrophilic aromatic substitution into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final topic in this module, synthesis planning carries the completed idea into nucleophilic aromatic substitution and benzylic chemistry.', 2),
  ('ae2a96bc-4467-4a33-bb50-2d9b224771cc', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Nucleophilic aromatic substitution and benzylic chemistry', 'This module builds directly on electrophilic aromatic substitution and develops nucleophilic aromatic substitution and benzylic chemistry. It belongs here because its methods and distinctions are prerequisites for alcohols, ethers, and epoxides.', 3),
  ('1ed59c06-2f64-4f96-96ed-b4d58fed5390', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'ae2a96bc-4467-4a33-bb50-2d9b224771cc', 'subtopic'::public.curated_course_node_type, 'Addition–elimination', 'Addition–elimination supplies the causal sequence within nucleophilic aromatic substitution and benzylic chemistry, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before radicals because that next topic assumes this starting point.', 0),
  ('f3356b32-5629-4956-9630-d02afdb6169c', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'ae2a96bc-4467-4a33-bb50-2d9b224771cc', 'subtopic'::public.curated_course_node_type, 'Radicals', 'Radicals identifies a specific object, distinction, or relationship within nucleophilic aromatic substitution and benzylic chemistry. Learners need to recognize and use it before combining this module''s ideas in later work. After addition–elimination, radicals supplies what is needed to address oxidation.', 1),
  ('eff3668c-4f84-4ca7-99b8-a7725a9db5d9', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'ae2a96bc-4467-4a33-bb50-2d9b224771cc', 'subtopic'::public.curated_course_node_type, 'Oxidation', 'Oxidation supplies the causal sequence within nucleophilic aromatic substitution and benzylic chemistry, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. As the final topic in this module, oxidation carries the completed idea into alcohols, ethers, and epoxides.', 2),
  ('5d8becb9-0737-4432-9b41-9e92ed6c8373', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Alcohols, ethers, and epoxides', 'This module builds directly on nucleophilic aromatic substitution and benzylic chemistry and develops alcohols, ethers, and epoxides. It belongs here because its methods and distinctions are prerequisites for aldehydes and ketones.', 4),
  ('3fc89804-3bb8-4015-ae8f-d6e24415a254', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '5d8becb9-0737-4432-9b41-9e92ed6c8373', 'subtopic'::public.curated_course_node_type, 'Synthesis', 'Synthesis turns the theory of alcohols, ethers, and epoxides into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. It appears before activation because that next topic assumes this starting point.', 0),
  ('ff0e7c63-20c7-4700-87e2-62f8018773b0', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '5d8becb9-0737-4432-9b41-9e92ed6c8373', 'subtopic'::public.curated_course_node_type, 'Activation', 'Activation identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module''s ideas in later work. After synthesis, activation supplies what is needed to address ring opening.', 1),
  ('a471a95e-f46a-4ebf-865c-8ee70cfd51f4', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '5d8becb9-0737-4432-9b41-9e92ed6c8373', 'subtopic'::public.curated_course_node_type, 'Ring opening', 'Ring opening identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module''s ideas in later work. After activation, ring opening supplies what is needed to address protecting strategies.', 2),
  ('43dddf61-c6a9-47f2-81db-bfd1645043c5', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '5d8becb9-0737-4432-9b41-9e92ed6c8373', 'subtopic'::public.curated_course_node_type, 'Protecting strategies', 'Protecting strategies identifies a specific object, distinction, or relationship within alcohols, ethers, and epoxides. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, protecting strategies carries the completed idea into aldehydes and ketones.', 3),
  ('2f3d1837-5217-4a9d-8507-3802c69e3912', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Aldehydes and ketones', 'This module builds directly on alcohols, ethers, and epoxides and develops aldehydes and ketones. It belongs here because its methods and distinctions are prerequisites for enols and enolates.', 5),
  ('fd808820-a17a-40e2-a6b8-fa8a6a304554', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '2f3d1837-5217-4a9d-8507-3802c69e3912', 'subtopic'::public.curated_course_node_type, 'Nucleophilic addition', 'Nucleophilic addition supplies the causal sequence within aldehydes and ketones, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before hydrates because that next topic assumes this starting point.', 0),
  ('67894a07-8c7f-41b5-92dc-24300ca88844', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '2f3d1837-5217-4a9d-8507-3802c69e3912', 'subtopic'::public.curated_course_node_type, 'Hydrates', 'Hydrates identifies a specific object, distinction, or relationship within aldehydes and ketones. Learners need to recognize and use it before combining this module''s ideas in later work. After nucleophilic addition, hydrates supplies what is needed to address acetals.', 1),
  ('ec36292c-83c1-48c1-9a3f-b49df9b9f3b2', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '2f3d1837-5217-4a9d-8507-3802c69e3912', 'subtopic'::public.curated_course_node_type, 'Acetals', 'Acetals identifies a specific object, distinction, or relationship within aldehydes and ketones. Learners need to recognize and use it before combining this module''s ideas in later work. After hydrates, acetals supplies what is needed to address imines.', 2),
  ('7e7c25d6-d11d-445c-a84e-b202df8ecfcd', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '2f3d1837-5217-4a9d-8507-3802c69e3912', 'subtopic'::public.curated_course_node_type, 'Imines', 'Imines identifies a specific object, distinction, or relationship within aldehydes and ketones. Learners need to recognize and use it before combining this module''s ideas in later work. After acetals, imines supplies what is needed to address wittig reaction.', 3),
  ('ae8602e5-4d78-4c0d-84a8-f3d28c0a01cc', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '2f3d1837-5217-4a9d-8507-3802c69e3912', 'subtopic'::public.curated_course_node_type, 'Wittig reaction', 'Wittig reaction supplies the causal sequence within aldehydes and ketones, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. As the final topic in this module, wittig reaction carries the completed idea into enols and enolates.', 4),
  ('07035e09-d241-4fa2-9ed8-8a42abdf3850', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Enols and enolates', 'This module builds directly on aldehydes and ketones and develops enols and enolates. It belongs here because its methods and distinctions are prerequisites for aldol and conjugate addition.', 6),
  ('fec3e7ab-b844-4784-9946-64816b14682d', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '07035e09-d241-4fa2-9ed8-8a42abdf3850', 'subtopic'::public.curated_course_node_type, 'Acidity', 'Acidity identifies a specific object, distinction, or relationship within enols and enolates. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before kinetic/thermodynamic control because that next topic assumes this starting point.', 0),
  ('a34afa71-6219-4d2b-8e97-03ae282554ec', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '07035e09-d241-4fa2-9ed8-8a42abdf3850', 'subtopic'::public.curated_course_node_type, 'Kinetic/thermodynamic control', 'Kinetic/thermodynamic control explains how enols and enolates behaves under misuse, faults, or constraints, which is essential for responsible real-world application. After acidity, kinetic/thermodynamic control supplies what is needed to address alkylation.', 1),
  ('e735b699-335e-458d-97b9-a216cc732912', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '07035e09-d241-4fa2-9ed8-8a42abdf3850', 'subtopic'::public.curated_course_node_type, 'Alkylation', 'Alkylation identifies a specific object, distinction, or relationship within enols and enolates. Learners need to recognize and use it before combining this module''s ideas in later work. After kinetic/thermodynamic control, alkylation supplies what is needed to address haloform.', 2),
  ('4ded2b8d-5915-4585-82c6-fcb39ac30bcc', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '07035e09-d241-4fa2-9ed8-8a42abdf3850', 'subtopic'::public.curated_course_node_type, 'Haloform', 'Haloform identifies a specific object, distinction, or relationship within enols and enolates. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, haloform carries the completed idea into aldol and conjugate addition.', 3),
  ('d5bc44c8-f03e-4748-95f5-ab469f96a374', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Aldol and conjugate addition', 'This module builds directly on enols and enolates and develops aldol and conjugate addition. It belongs here because its methods and distinctions are prerequisites for carboxylic acids and derivatives.', 7),
  ('d997f95f-d592-4f2f-b266-f19d0d967958', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'd5bc44c8-f03e-4748-95f5-ab469f96a374', 'subtopic'::public.curated_course_node_type, 'Condensation', 'Condensation identifies a specific object, distinction, or relationship within aldol and conjugate addition. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before michael reaction because that next topic assumes this starting point.', 0),
  ('fe026fe2-8572-4eaf-b052-9b1905677932', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'd5bc44c8-f03e-4748-95f5-ab469f96a374', 'subtopic'::public.curated_course_node_type, 'Michael reaction', 'Michael reaction supplies the causal sequence within aldol and conjugate addition, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After condensation, michael reaction supplies what is needed to address robinson annulation.', 1),
  ('86c44f8b-bcc0-4ea5-93c4-bc3d67bc0e77', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'd5bc44c8-f03e-4748-95f5-ab469f96a374', 'subtopic'::public.curated_course_node_type, 'Robinson annulation', 'Robinson annulation identifies a specific object, distinction, or relationship within aldol and conjugate addition. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, robinson annulation carries the completed idea into carboxylic acids and derivatives.', 2),
  ('b4998e1b-458a-4161-aad7-07f16319144c', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Carboxylic acids and derivatives', 'This module builds directly on aldol and conjugate addition and develops carboxylic acids and derivatives. It belongs here because its methods and distinctions are prerequisites for amines.', 8),
  ('182fd003-fb40-451d-89ef-2884adf0f1e5', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'b4998e1b-458a-4161-aad7-07f16319144c', 'subtopic'::public.curated_course_node_type, 'Acyl substitution', 'Acyl substitution supplies the causal sequence within carboxylic acids and derivatives, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. It appears before reductions because that next topic assumes this starting point.', 0),
  ('c94d94cf-a471-468d-aaba-643fbfea4255', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'b4998e1b-458a-4161-aad7-07f16319144c', 'subtopic'::public.curated_course_node_type, 'Reductions', 'Reductions supplies the causal sequence within carboxylic acids and derivatives, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After acyl substitution, reductions supplies what is needed to address organometallic reactions.', 1),
  ('abea1b35-1b73-4cea-b412-7aecb2299967', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', 'b4998e1b-458a-4161-aad7-07f16319144c', 'subtopic'::public.curated_course_node_type, 'Organometallic reactions', 'Organometallic reactions supplies the causal sequence within carboxylic acids and derivatives, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. As the final topic in this module, organometallic reactions carries the completed idea into amines.', 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9805fdad-9e7e-4b19-b729-fd67399fe785', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Amines', 'This module builds directly on carboxylic acids and derivatives and develops amines. It belongs here because its methods and distinctions are prerequisites for biomolecules.', 9),
  ('216c5124-8d28-47eb-a156-8e23392168e3', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '9805fdad-9e7e-4b19-b729-fd67399fe785', 'subtopic'::public.curated_course_node_type, 'Basicity', 'Basicity identifies a specific object, distinction, or relationship within amines. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before synthesis because that next topic assumes this starting point.', 0),
  ('696b949b-260d-4f78-81ea-16512e3b77af', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '9805fdad-9e7e-4b19-b729-fd67399fe785', 'subtopic'::public.curated_course_node_type, 'Synthesis', 'Synthesis turns the theory of amines into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. After basicity, synthesis supplies what is needed to address diazonium chemistry.', 1),
  ('6669f961-5ea7-4782-ac4a-9d0b463dff6c', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '9805fdad-9e7e-4b19-b729-fd67399fe785', 'subtopic'::public.curated_course_node_type, 'Diazonium chemistry', 'Diazonium chemistry identifies a specific object, distinction, or relationship within amines. Learners need to recognize and use it before combining this module''s ideas in later work. After synthesis, diazonium chemistry supplies what is needed to address heterocycle introduction.', 2),
  ('c29eb54b-2654-45e1-8da7-00644b0825ad', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '9805fdad-9e7e-4b19-b729-fd67399fe785', 'subtopic'::public.curated_course_node_type, 'Heterocycle introduction', 'Heterocycle introduction identifies a specific object, distinction, or relationship within amines. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, heterocycle introduction carries the completed idea into biomolecules.', 3),
  ('53182f2c-27d9-4303-bcde-a93eeced16b4', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Biomolecules', 'This module builds directly on amines and develops biomolecules. It belongs here because its methods and distinctions are prerequisites for retrosynthesis and selectivity.', 10),
  ('8eae8dbd-e66e-4f6f-b87c-9e8df6c4a9c3', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '53182f2c-27d9-4303-bcde-a93eeced16b4', 'subtopic'::public.curated_course_node_type, 'Carbohydrates', 'Carbohydrates identifies a specific object, distinction, or relationship within biomolecules. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before amino acids because that next topic assumes this starting point.', 0),
  ('362f5fac-1c5d-4ecb-835d-2eec142fbee3', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '53182f2c-27d9-4303-bcde-a93eeced16b4', 'subtopic'::public.curated_course_node_type, 'Amino acids', 'Amino acids identifies a specific object, distinction, or relationship within biomolecules. Learners need to recognize and use it before combining this module''s ideas in later work. After carbohydrates, amino acids supplies what is needed to address peptides.', 1),
  ('3d08bb33-ee2a-4f1e-92cb-f3b1e778373b', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '53182f2c-27d9-4303-bcde-a93eeced16b4', 'subtopic'::public.curated_course_node_type, 'Peptides', 'Peptides identifies a specific object, distinction, or relationship within biomolecules. Learners need to recognize and use it before combining this module''s ideas in later work. After amino acids, peptides supplies what is needed to address lipids.', 2),
  ('24ff954c-f7d9-44dc-b867-07d239ae6103', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '53182f2c-27d9-4303-bcde-a93eeced16b4', 'subtopic'::public.curated_course_node_type, 'Lipids', 'Lipids identifies a specific object, distinction, or relationship within biomolecules. Learners need to recognize and use it before combining this module''s ideas in later work. After peptides, lipids supplies what is needed to address nucleic-acid chemistry.', 3),
  ('8727a78f-bbcd-4283-be47-81351b3a846e', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '53182f2c-27d9-4303-bcde-a93eeced16b4', 'subtopic'::public.curated_course_node_type, 'Nucleic-acid chemistry', 'Nucleic-acid chemistry identifies a specific object, distinction, or relationship within biomolecules. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, nucleic-acid chemistry carries the completed idea into retrosynthesis and selectivity.', 4),
  ('61bc5f43-1ac7-4b3d-a2a0-4e4f77082099', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', null, 'topic'::public.curated_course_node_type, 'Retrosynthesis and selectivity', 'This culminating module draws on biomolecules and develops retrosynthesis and selectivity. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('df0fd8ed-11c5-47f5-ad44-e349669f69d1', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '61bc5f43-1ac7-4b3d-a2a0-4e4f77082099', 'subtopic'::public.curated_course_node_type, 'Synthons', 'Synthons identifies a specific object, distinction, or relationship within retrosynthesis and selectivity. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before protecting groups because that next topic assumes this starting point.', 0),
  ('20b955da-d5e8-43d6-a75a-276d127520ab', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '61bc5f43-1ac7-4b3d-a2a0-4e4f77082099', 'subtopic'::public.curated_course_node_type, 'Protecting groups', 'Protecting groups identifies a specific object, distinction, or relationship within retrosynthesis and selectivity. Learners need to recognize and use it before combining this module''s ideas in later work. After synthons, protecting groups supplies what is needed to address chemoselectivity.', 1),
  ('bfef6e13-bd0e-4350-bd84-a8be747fd005', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '61bc5f43-1ac7-4b3d-a2a0-4e4f77082099', 'subtopic'::public.curated_course_node_type, 'Chemoselectivity', 'Chemoselectivity identifies a specific object, distinction, or relationship within retrosynthesis and selectivity. Learners need to recognize and use it before combining this module''s ideas in later work. After protecting groups, chemoselectivity supplies what is needed to address literature route critique.', 2),
  ('da8ccf58-ce25-484e-8c6d-8c9542b2d3ac', '7b4cb39e-f130-4bcb-bb47-2f7db73c0a84', '61bc5f43-1ac7-4b3d-a2a0-4e4f77082099', 'subtopic'::public.curated_course_node_type, 'Literature route critique', 'Literature route critique identifies a specific object, distinction, or relationship within retrosynthesis and selectivity. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, literature route critique requires ideas from the complete path to be integrated and transferred.', 3);
